/// <summary>
/// PricingAttribute of table <c>MCRCustCategory</c> field ParentCategory.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Customer, GUPPricingAttributeSourceLevel::Header)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(MCRCustCategory, ParentCategory))]
internal class GUPPricingAttributeMCRCustCategoryParentCategory extends GUPPricingAttributeMCRCustCategory implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(MCRCustCategory, ParentCategory);
}

public str getRefValue(Str _defaultValue)
{
    MCRCustCategory mCRcustCategory;
    str ret = "";
    boolean isFirstAttributeToAppend = true;
    Query query = new Query();
    query.addDataSource(tableNum(MCRCustCategory)).addRange(fieldNum(MCRCustCategory, RecId)).value(_defaultValue);
    QueryRun qr = new QueryRun(query);
    while (qr.next())
    {
        mCRcustCategory = qr.get(tableNum(MCRCustCategory), 1);
        if (!isFirstAttributeToAppend)
        {
            ret += ",";
        }
        else
        {
            isFirstAttributeToAppend = false;
        }
        ret += mCRcustCategory.name;
    }

    return ret;
}

public boolean validate(Str _defaultValue)
{
    var recId = str2Int64(_defaultValue);
    return MCRCustCategory::find(recId) ? true : false;
}

public void lookupAllowedValues(object _formStringControl)
{
    GUPMCRCustCategoryLookup custCategoryLookup = new GUPMCRCustCategoryLookup(true);
    //custCategoryLookup.parmreturnRefRecID(true);
    custCategoryLookup.performLookup(_formStringControl);

}
